UPDATE  device_standard
SET update_time = NOW()

    , standard_name = #{standardName}


    , standard_description = #{standardDescription}

WHERE id = #{id}

mapper.select:
SELECT id, standard_name, standard_description, create_time, update_time, create_user
FROM device_standard
WHERE standard_status != '0'

    AND standard_name LIKE CONCAT('%', #{queryParam.standardName}, '%') ESCAPE '#'


    AND create_time >= #{queryParam.beginTime}


    AND create_time <= #{queryParam.endTime}


    AND create_user LIKE CONCAT('%', #{queryParam.createUser}, '%') ESCAPE '#'

ORDER BY create_time DESC, update_time DESC
LIMIT #{offset}, #{validPageSize}

SELECT COUNT(*) FROM device_standard WHERE standard_status != '0'
AND standard_name LIKE CONCAT('%', #{queryParam.standardName}, '%') ESCAPE '#'
AND create_time >= #{queryParam.beginTime}
AND create_time <= #{queryParam.endTime}
AND create_user LIKE CONCAT('%', #{queryParam.createUser}, '%') ESCAPE '#'
